import { GoogleGenAI } from '@google/genai';
import { readFileSync } from 'fs';
const env = Object.fromEntries(
  readFileSync('.env.local','utf8').split('\n').filter(l=>l&&!l.startsWith('#')).map(l=>{const i=l.indexOf('='); return [l.slice(0,i), l.slice(i+1).replace(/^[\"']|[\"']$/g,'')];})
);
const ai = new GoogleGenAI({ apiKey: env.GEMINI_API_KEY });
try {
  const r = await ai.models.generateContent({ model: 'gemini-2.5-flash-lite', contents: 'say pong' });
  console.log('OK', (r.text||'').slice(0,80));
} catch (e) {
  console.error('ERR', e.message);
  if (e.cause) console.error('cause', e.cause);
  console.error(String(e).slice(0,500));
}
"

